import java.util.Scanner;

public class Main {
    public static void try_digit(int d) {
        if (d == 0) System.out.printf("O-|-OOOO%n");
        if (d == 1) System.out.printf("O-|O-OOO%n");
        if (d == 2) System.out.printf("O-|OO-OO%n");
        if (d == 3) System.out.printf("O-|OOO-O%n");
        if (d == 4) System.out.printf("O-|OOOO-%n");
        if (d == 5) System.out.printf("-O|-OOOO%n");
        if (d == 6) System.out.printf("-O|O-OOO%n");
        if (d == 7) System.out.printf("-O|OO-OO%n");
        if (d == 8) System.out.printf("-O|OOO-O%n");
        if (d == 9) System.out.printf("-O|OOOO-%n");
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        if (n == 0) {
            try_digit(0);
        } else {
            while (n >= 1) {
                try_digit(n % 10);
                n = n / 10;
            }
        }
        scanner.close();
    }
}

